@Override
public void drain() {
    if (getAndIncrement() != 0) {
        return;
    }

    int missed = 1;
    InnerQueuedSubscriber<R> inner = current;
    Subscriber<? super R> a = downstream;
    ErrorMode em = errorMode;
    for(;;) {
        long r = requested.get();
        long e = 0L;
        if (inner == null) {
            if (em != ErrorMode.END) {
                Throwable ex = errors.get();
                if (ex != null) {
                    cancelAll();
                    errors.tryTerminateConsumer(downstream);
                    return;
                }
            }
            boolean outerDone = done;
            inner = subscribers.poll();
            if (outerDone && inner == null) {
                errors.tryTerminateConsumer(downstream);
                return;
            }
            if (inner != null) {
                current = inner;
            }
        }
        boolean continueNextSource = false;
        if (inner != null) {
            SimpleQueue<R> q = inner.queue();
            if (q != null) {
                while (e != r) {
                    if (cancelled) {
                        cancelAll();
                        return;
                    }
                    if (em == ErrorMode.IMMEDIATE) {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            current = null;
                            inner.cancel();
                            cancelAll();
                            errors.tryTerminateConsumer(downstream);
                            return;
                        }
                    }
                    boolean d = inner.isDone();
                    R v;
                    try {
                        v = q.poll();
                    } catch (Throwable ex) {
                        Exceptions.throwIfFatal(ex);
                        current = null;
                        inner.cancel();
                        cancelAll();
                        a.onError(ex);
                        return;
                    }
                    boolean empty = v == null;
                    if (d && empty) {
                        inner = null;
                        current = null;
                        upstream.request(1);
                        continueNextSource = true;
                        break;
                    }
                    if (empty) {
                        break;
                    }
                    a.onNext(v);
                    e++;
                    inner.request(1L);
                }
                if (e == r) {
                    if (cancelled) {
                        cancelAll();
                        return;
                    }
                    if (em == ErrorMode.IMMEDIATE) {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            current = null;
                            inner.cancel();
                            cancelAll();
                            errors.tryTerminateConsumer(downstream);
                            return;
                        }
                    }
                    boolean d = inner.isDone();
                    boolean empty = q.isEmpty();
                    if (d && empty) {
                        inner = null;
                        current = null;
                        upstream.request(1);
                        continueNextSource = true;
                    }
                }
            }
        }
        if (e != 0L && r != Long.MAX_VALUE) {
            requested.addAndGet(-e);
        }
        if (continueNextSource) {
            continue;
        }
        missed = addAndGet(-missed);
        if (missed == 0) {
            break;
        }
    }
}

    public List<ThreadVO> sample(Collection<ThreadVO> originThreads) {
        List<ThreadVO> threads = new ArrayList<ThreadVO>(originThreads);

        // Sample CPU
        if (lastCpuTimes.isEmpty()) {
        lastSampleTimeNanos = System.nanoTime();


        for (ThreadVO thread : threads) {
            if (thread.getId() > 0) {
            long cpu = threadMXBean.getThreadCpuTime(thread.getId());
            lastCpuTimes.put(thread, cpu);
            thread.setTime(cpu/1000000);
            }
        }

            // add internal threads

        Map<String, Long> internalThreadCpuTimes = getInternalThreadCpuTimes();
        if (internalThreadCpuTimes != null) {
        for (Map.Entry<String, Long> entry : internalThreadCpuTimes.entrySet()) {
            String key = entry.getKey();
            ThreadVO thread = createThreadVO(key);
            thread.setTime(entry.getValue()/1000000);
            threads.add(thread);
            lastCpuTimes.put(thread, entry.getValue());
        }
        }

            //sort by time
        Collections.sort(threads, new Comparator<ThreadVO>() {
    @Override
    public int compare(ThreadVO o1, ThreadVO o2) {
        long l1 = o1.getTime();
        long l2 = o2.getTime();
        if (l1 < l2) {
            return 1;
        } else if (l1 > l2) {
                   return -1;
                   } else {
                   return 0;
        }
    }

                                  });
        return threads;
        }

        // Resample

        long newSampleTimeNanos = System.nanoTime();
        Map<ThreadVO, Long> newCpuTimes = new HashMap<ThreadVO, Long>(threads.size());
        for (ThreadVO thread : threads) {
            if (thread.getId() > 0) {
            long cpu = threadMXBean.getThreadCpuTime(thread.getId());
            newCpuTimes.put(thread, cpu);
            }
        }
        // internal threads

        Map<String, Long> newInternalThreadCpuTimes = getInternalThreadCpuTimes();
        if (newInternalThreadCpuTimes != null) {
        for (Map.Entry<String, Long> entry : newInternalThreadCpuTimes.entrySet()) {
            ThreadVO threadVO = createThreadVO(entry.getKey());
            threads.add(threadVO);
            newCpuTimes.put(threadVO, entry.getValue());
        }
        }

        // Compute delta time

        final Map<ThreadVO, Long> deltas = new HashMap<ThreadVO, Long>(threads.size());
        for (ThreadVO thread : newCpuTimes.keySet()) {
            Long t = lastCpuTimes.get(thread);
            if (t == null) {
            t = 0L;
            }

            long time1 = t;
            long time2 = newCpuTimes.get(thread);
            if (time1 == -1) {
                time1 = time2;
            } else if (time2 == -1) {
                   time2 = time1;
                   }

            long delta = time2 - time1;
            deltas.put(thread, delta);
        }

        long sampleIntervalNanos = newSampleTimeNanos - lastSampleTimeNanos;

        // Compute cpu usage
        final HashMap<ThreadVO, Double> cpuUsages = new HashMap<ThreadVO, Double>(threads.size());
        for (ThreadVO thread : threads) {
            double cpu = sampleIntervalNanos == 0 ? 0 : (Math.rint(deltas.get(thread)*10000.0/sampleIntervalNanos)/100.0);
            cpuUsages.put(thread, cpu);
        }

        // Sort by CPU time : should be a rendering hint...
        Collections.sort(threads, new Comparator<ThreadVO>() {
@Override
public int compare(ThreadVO o1, ThreadVO o2) {
    long l1 = deltas.get(o1);
    long l2 = deltas.get(o2);
    if (l1 < l2) {
        return 1;
    } else if (l1 > l2) {
               return -1;
               } else {
               return 0;
    }
}

                                  });


        for (ThreadVO thread : threads) {
            //nanos to mills
            long timeMills = newCpuTimes.get(thread)/1000000;
            long deltaTime = deltas.get(thread)/1000000;
            double cpu = cpuUsages.get(thread);
            thread.setCpu(cpu);
            thread.setTime(timeMills);
            thread.setDeltaTime(deltaTime);
        }
        lastCpuTimes = newCpuTimes;
        lastSampleTimeNanos = newSampleTimeNanos;
        return threads;
    }

@Override
int process(SharpStream out, SharpStream... sources) throws IOException {
    // check if the subtitle is already in srt and copy, this should never happen
    String format = getArgumentAt(0, null);
    boolean ignoreEmptyFrames = getArgumentAt(1, "true").equals("true");
    if (format == null || format.equals("ttml")) {
        SrtFromTtmlWriter writer = new SrtFromTtmlWriter(out, ignoreEmptyFrames);

        try {
            writer.build(sources[0]);
        } catch (Exception err) {
            Log.e(TAG, "subtitle parse failed", err);
            return err instanceof IOException? 1: 8;
        }
        return OK_RESULT;
    } else if (format.equals("srt")) {
               byte[] buffer = new byte[8* 1024];
               int read;

               while ((read = sources[0].read(buffer)) > 0) {
                   out.write(buffer, 0, read);
               }
               return OK_RESULT;
           }

    throw new UnsupportedOperationException("Can't convert this subtitle, unimplemented format: " + format);
}

public static AdminServer createAdminServer() {
    if (!"false".equals(System.getProperty("zookeeper.admin.enableServer"))) {
        try {
            Class<?> jettyAdminServerC = Class.forName("org.apache.zookeeper.server.admin.JettyAdminServer");
            Object adminServer = jettyAdminServerC.getConstructor().newInstance();
            return (AdminServer) adminServer;
        } catch (ClassNotFoundException e) {
            LOG.warn("Unable to start JettyAdminServer", e);
        } catch (InstantiationException e) {
            LOG.warn("Unable to start JettyAdminServer", e);
        } catch (IllegalAccessException e) {
            LOG.warn("Unable to start JettyAdminServer", e);
        } catch (InvocationTargetException e) {
            LOG.warn("Unable to start JettyAdminServer", e);
        } catch (NoSuchMethodException e) {
            LOG.warn("Unable to start JettyAdminServer", e);
        } catch (NoClassDefFoundError e) {
            LOG.warn("Unable to load jetty, not starting JettyAdminServer", e);
        }
    }
    return new DummyAdminServer();
}

void drainFused() {
    int missed = 1;

    for (;;) {
        if (disposed) {
            return;
        }

        boolean d = done;
        Throwable ex = error;

        if (!delayError && d && ex != null) {
            disposed = true;
            downstream.onError(error);
            worker.dispose();
            return;
        }

        downstream.onNext(null);

        if (d) {
            disposed = true;
            ex = error;

            if (ex != null) {
                downstream.onError(ex);
            } else {
                downstream.onComplete();
            }

            worker.dispose();
            return;
        }

        missed = addAndGet(-missed);

        if (missed == 0) {
            break;
        }
    }
}

